WITH dim_totals AS (SELECT s.country, s.city, e.brand, COUNT(*) AS num_rows, MIN(e.stock_qty) AS min_stock_qty, GROUPING_ID() AS grouping_level FROM products e LEFT JOIN suppliers s ON e.supplier_id = s.id GROUP BY GROUPING SETS ((s.country, s.city, e.brand), (s.country, s.city), (s.country))) SELECT country, brand, num_rows, grouping_level, CASE WHEN country RLIKE '^(SG|UK)$' THEN 'CORE' ELSE 'GROUP_A' END AS country_zone FROM dim_totals ORDER BY country_zone DESC
